# try minimal PDF text extraction
import re, zlib
data = open('extrato_maio_2026.pdf','rb').read()
texts=[]
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    s=m.group(1)
    try: d=zlib.decompress(s)
    except Exception: d=s
    for t in re.findall(rb'\((.*?)\)\s*Tj|\[(.*?)\]\s*TJ', d, re.S):
        frag=b''.join(t).replace(b')Tj(',b'').replace(b'(',b'').replace(b')',b'')
        if frag.strip(): texts.append(frag.decode('latin-1'))
print('\n'.join(texts) if texts else 'NO TEXT FRAGMENTS EXTRACTED')
EOF"}

